package projects.ratelimiter.ratelimiters;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;
import projects.ratelimiter.RateLimiter;
import projects.ratelimiter.RateLimiterConfig;

public class ClassicRateLimiter extends RateLimiter {
    private final Map<String, Integer> requestCounts = new HashMap<>();
    private final Map<String, Instant> windowStartTimes = new HashMap<>();

    @Override
    public boolean allowRequest(String userId, RateLimiterConfig config){
        Instant windowStart = windowStartTimes.get(userId);
        Instant now = Instant.now();

        // First ever request or window of last request is ended
        if (windowStart == null || now.isAfter(windowStart.plus(config.getWindowDuration()))) {
            windowStartTimes.put(userId, now);
            requestCounts.put(userId, 1);
            return true;
        }
        int requestCount = requestCounts.get(userId);

        // Rate limited
        if (requestCount >= config.getRequestCount()) {
            return false;
        }

        requestCounts.put(userId, requestCount + 1);

        return true;
    }
}

package projects.ratelimiter.ratelimiters;
import java.time.Instant;
import java.util.HashMap;
import java.util.LinkedList;
import java.util.Map;
import java.util.Queue;

import projects.ratelimiter.RateLimiter;
import projects.ratelimiter.RateLimiterConfig;

public class SlidingWindowRateLimiter extends RateLimiter {
    private final Map<String, Queue<Instant>> requests = new HashMap<>();

    @Override
    public boolean allowRequest(String userId, RateLimiterConfig config){
        Queue<Instant> existingRequests = requests.get(userId);
        Instant now = Instant.now();

        if (existingRequests == null) {
            existingRequests = new LinkedList<>();
        }

        Instant allowedStart = now.minus(config.getWindowDuration());
        while (existingRequests.size() != 0 && existingRequests.peek().isBefore(allowedStart)) {
            existingRequests.poll();
        }

        // First ever request or window of last request is ended
        if (existingRequests.size() == 0) {
            existingRequests.offer(now);
            requests.put(userId, existingRequests);
            return true;
        }

        // Rate limited
        if (existingRequests.size() >= config.getRequestCount()) {
            return false;
        }

        existingRequests.offer(now);

        return true;
    }
}

package projects.ratelimiter.ratelimiters;
import java.time.*;
import java.util.*;

import projects.ratelimiter.RateLimiter;
import projects.ratelimiter.RateLimiterConfig;

public class TokenBucketRateLimiter extends RateLimiter {
    private final Map<String, TokenBucketState> buckets = new HashMap<>();

    @Override
    public boolean allowRequest(String userId, RateLimiterConfig config){
        Instant now = Instant.now();

        TokenBucketState currentState = buckets.get(userId);

        if (currentState == null) {
            currentState = new TokenBucketState(config.getRequestCount()-1, now);
            buckets.put(userId, currentState);
            return true;
        }

        Duration timeElapsed = Duration.between(currentState.getLastRefillTime(), now);
        double tokensPerMs = (double) config.getRequestCount() / config.getWindowDuration().toMillis();
        double newTokens = timeElapsed.toMillis() * tokensPerMs;

        double newAvailableTokens = currentState.getAvailableTokens() + newTokens;

        if (newAvailableTokens >= 1) {
            currentState.setAvailableTokens(newAvailableTokens - 1);
            currentState.setLastRefillTime(now);
            return true;
        }

        return false;
    }
}

package projects.ratelimiter.ratelimiters;

import java.time.Instant;

public class TokenBucketState {
    private double availableTokens;
    private Instant lastRefillTime;

    public TokenBucketState(double availableTokens, Instant lastRefillTime) {
        this.availableTokens = availableTokens;
        this.lastRefillTime = lastRefillTime;
    }

    public double getAvailableTokens() {
        return availableTokens;
    }

    public void setAvailableTokens(double availableTokens) {
        this.availableTokens = availableTokens;
    }

    public Instant getLastRefillTime() {
        return lastRefillTime;
    }

    public void setLastRefillTime(Instant lastRefillTime) {
        this.lastRefillTime = lastRefillTime;
    }
}

